use axum::{http::StatusCode, routing::post, Json, Router};
use serde::{Deserialize, Serialize};

#[derive(Debug, Deserialize)]
struct Numbers {
    a: i32,
    b: i32,
}

#[derive(Debug, Serialize)]
struct ResultBody {
    result: i32,
}

#[derive(Debug, Serialize)]
struct ErrorBody {
    error: String,
}

fn validate(payload: &Numbers) -> Result<(), (StatusCode, Json<ErrorBody>)> {
    if payload.a < 0 || payload.b < 0 {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(ErrorBody {
                error: "inputs must be non-negative".to_string(),
            }),
        ));
    }
    Ok(())
}

async fn sum(Json(payload): Json<Numbers>) -> Result<Json<ResultBody>, (StatusCode, Json<ErrorBody>)> {
    validate(&payload)?;
    Ok(Json(ResultBody { result: payload.a + payload.b }))
}

async fn product(
    Json(payload): Json<Numbers>,
) -> Result<Json<ResultBody>, (StatusCode, Json<ErrorBody>)> {
    validate(&payload)?;
    Ok(Json(ResultBody { result: payload.a * payload.b }))
}

#[tokio::main]
async fn main() {
    let app = Router::new()
        .route("/sum", post(sum))
        .route("/product", post(product));
    let listener = tokio::net::TcpListener::bind("0.0.0.0:8044").await.unwrap();
    axum::serve(listener, app).await.unwrap();
}
